    "shenzhen-ns": ["深圳南山店", "Lone Star BBQ House - Austin, TX 78701"],
    M00000004: ["Nai Cha", "nai cha", "奶茶", "北京旗舰店"],
    "flagship-nyc": ["Nai Cha", "北京旗舰店"],
